(()=>{
  const D=window.GAME_DATA,leadership=/(Senior|Lead|Manager|Director|Foreman|Principal|Captain|Superintendent|Partner|VP|Chief|Head|Senior NCO)/i,need={3:2,4:4,5:7,6:10,7:12};
  for(const j of Object.values(D.jobs)){
    if((j.level||0)>=3&&leadership.test(j.name)&&!j.requirements.some(r=>r.type==='trackExperienceMin'))j.requirements.push({type:'trackExperienceMin',track:j.track,value:need[j.level]||2});
  }
})();

