// v0.7.9.4 — Quality & Stability
(()=>{
  const D=window.GAME_DATA;
  D.version='0.7.9.4';
  D.architecture='data-core-9-4-quality-stability';
  D.saveSchemaVersion=6;

  D.ageAccess={
    lifestyle:18,
    savings:13,
    investing:18,
    borrowing:18,
    bankruptcy:18,
    possessions:8
  };

  // Ownership ages live in data rather than action-handler condition piles.
  for(const item of Object.values(D.inventoryCatalog||{})){
    if(item.minAge==null)item.minAge=item.type==='Vehicle'?16:(item.assetClass==='Collectible'?18:(item.assetClass==='Tech'?12:8));
  }

  // Science now participates in older science content and science-career qualification.
  const scienceFair=(D.events||[]).find(e=>e.id==='scienceFair');
  if(scienceFair?.choices?.[0])scienceFair.choices[0].effect={...(scienceFair.choices[0].effect||{}),science:3,technology:1};
  if(scienceFair?.choices?.[1])scienceFair.choices[1].effect={...(scienceFair.choices[1].effect||{}),science:2};

  const scienceJobMinimums={labtech:35,sciencefellow:45,scientist:55,seniorscientist:62,principalscientist:70,datascientist:55,seniordatascientist:65};
  for(const [key,min] of Object.entries(scienceJobMinimums)){
    const job=D.jobs?.[key]; if(!job)continue;
    job.requirements=(job.requirements||[]).filter(r=>!(r.type==='skillMin'&&r.skill==='science'));
    job.requirements.push({type:'skillMin',skill:'science',value:min,label:`Science ${min}+`});
  }

  D.crimeRules={...(D.crimeRules||{}),caughtChanceMin:.02,caughtChanceMax:.98};
})();
